        new = c.evolve({"IsProd": True, "IsDev": False, "IsBig": True})
        assert new.status == {"IsProd": True, "IsDev": False, "IsBig": True}

    def test_evolve_empty_status_short_circuit(self):
        c = _make_simple_conditions()
        new = c.evolve({})
