        c = _make_compound_conditions()
        new = c.evolve({"IsProdAndBig": False, "IsAnyEnv": True, "NotProd": False})
        assert new.status == {
            "IsProdAndBig": False,
            "IsAnyEnv": True,
            "NotProd": False,
